package java_basics;

public class Switch {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a=12;
		
		switch(a) {
		
		case 12:
			System.out.println("12");
			break;
		
		case 13:
			System.out.println("13");
			break;
			
		case 14:
			System.out.println("14");
			break;
			
		default:
			System.out.println("Not Exist");
			break;
			
		}
		

	}

}
